@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Marcellus&display=swap');
:root{font-family:'DM Sans',sans-serif;color:#ede9df;background:#101512;font-synthesis:none;text-rendering:optimizeLegibility;--gold:#d4ad6e;--gold-bright:#f0cb87;--muted:#9a9d92;--panel:rgba(17,23,21,.88);--line:rgba(224,195,139,.19)}*{box-sizing:border-box}body{margin:0;overflow:hidden;background:#101512}button{font:inherit;color:inherit;cursor:pointer}#game{position:fixed;inset:0;z-index:0}canvas{display:block;width:100%;height:100%}.vignette{position:fixed;inset:0;z-index:1;pointer-events:none;background:linear-gradient(180deg,rgba(8,13,13,.68) 0%,transparent 20%,transparent 66%,rgba(8,12,10,.63) 100%),linear-gradient(90deg,rgba(8,12,10,.36),transparent 29%,transparent 75%,rgba(8,12,10,.26));box-shadow:inset 0 0 170px rgba(0,0,0,.4)}.topbar{position:fixed;z-index:3;top:0;left:0;right:0;height:74px;padding:0 34px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(232,212,176,.12);background:linear-gradient(180deg,rgba(10,15,14,.82),rgba(10,15,14,.26));}.brand{display:flex;align-items:center;gap:11px;width:255px}.brand-mark{width:37px;height:37px;display:grid;place-items:center;border:1px solid #c5a36d;color:#e5c28a;font:25px Marcellus,serif;transform:rotate(45deg);background:rgba(177,134,76,.1)}.brand-mark:first-letter{transform:rotate(-45deg)}.brand-name{font:18px Marcellus,serif;letter-spacing:4px;color:#f1e7d5}.brand-sub{font-size:8px;letter-spacing:2px;color:#aaa392;margin-top:3px}.realm-pill{font-size:10px;letter-spacing:1.55px;color:#c5c0b5;display:flex;align-items:center;gap:10px}.realm-pill b{color:#e0c18c;font-weight:600}.realm-dot,.live-dot{height:6px;width:6px;border-radius:50%;background:#c9a46c;box-shadow:0 0 10px #d5ab68}.realm-sep{color:#746f63}.top-right{display:flex;align-items:center;gap:24px}.clock{font-size:10px;letter-spacing:1px;color:#d4ccbb;display:flex;gap:8px;align-items:center}.sun-icon{font-size:17px;color:#e6c27f}.profile{display:flex;align-items:center;gap:10px;border-left:1px solid var(--line)