px;letter-spacing:1.1px;color:#aaa79c}.bar{margin:5px 0 4px}.bar i{display:block;height:100%;transition:width .25s}.hp i{width:86%;background:linear-gradient(90deg,#8a4037,#c26450)}.stamina i{width:72%;background:linear-gradient(90deg,#688750,#a3b775)}.vitals small{font-size:8px;color:#b9b4a9}.stats-row{border-top:1px solid rgba(255,255,255,.08);padding-top:10px;margin-top:12px;display:flex;justify-content:space-between;color:#aaa79d;font-size:8px;letter-spacing:.6px}.stats-row span:first-letter{color:#caa56a}.stats-row b{color:#e0d7c6;font-weight:500}.objective-panel{padding:15px 17px 12px}.gold-bar{width:3px;height:11px;background:#d2ac70;display:inline-block;margin-right:8px;vertical-align:-2px;box-shadow:0 0 8px rgba(210,172,112,.35)}.section-title{display:flex;align-items:center}.objective-panel h3{font:17px Marcellus,serif;margin:13px 0 5px;color:#e8dfcd}.objective-panel p{font-size:10px;line-height:1.55;color:#a8a69c}.quest-progress{margin-top:12px;padding:9px 10px;background:rgba(220,190,139,.055);border-left:1px solid rgba(220,190,139,.45);font-size:9px;color:#d0c8b8;display:flex;align-items:center;gap:8px}.quest-dot{height:5px;width:5px;background:#d6b372;border-radius:50%}.text-button{background:none;border:0;padding:12px 0 0;font-size:8px;letter-spacing:1.2px;color:#c6a674}.text-button span{font-size:12px;padding-left:4px}.nearby-panel{padding:13px 15px}.nearby-head{display:flex;align-items:center;justify-content:space-between}.range-label{font-size:7px;color:#85877d;letter-spacing:.8px}.nearby-list{margin-top:10px}.nearby-item{display:flex;align-items:center;gap:9px;padding:8px 0;border-top:1px solid rgba(255,255,255,.055)}.nearby-avatar{height:27px;width:27px;border-radius:50%;display:grid;place-items:center;border:1px solid rgba(212,173,110,.35);background:rgba(212,173,110,.11);color:#e0c088;font:13px Marcellus}.nearby-item strong{display:block;font:12px Marcellus;color:#e3ddcf}.nearby-item small{display:block;font-size:8px;color:#96968b;margin-top:3px}.nearby-distance{margin-left:auto;color:#a6a296;font-size:9px}.mini-map{padding:12px}.map-top{display:flex;justify-content:space-between;font-size:8px;letter-spacing:1.2px;color:#d1bd98}.map-coords{font-size:8px;letter-spacing:.2px;color:#918f84}.mini-map-art{height:145px;margin-top:10px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 34% 72%,rgba(97,115,74,.46),transparent 34%),radial-gradient(ellipse at 76% 18%,rgba(116,117,76,.38),transparent 33%),linear-gradient(135deg,#354438,#27352e 50%,#3d4536);border:1px solid rgba(208,187,145,.13)}.mini-map-art:before,.mini-map-art:after{content:'';position:absolute;inset:-40px;background-image:radial-gradient(ellipse,rgba(194,183,126,.22) 1px,transparent 2px);background-size:18px 16px;opacity:.5}.map-river{position:absolute;height:220px;width:30px;left:63%;top:-31px;transform:rotate(26deg);border-radius:50%;background:rgba(87,137,143,.55);filter:blur(5px)}.map-road{position:absolute;height:180%;width:2px;left:43%;top:-32%;transform:rotate(57deg);background:rgba(211,179,128,.5);box-shadow:0 0 5px rgba(217,185,132,.3)}.map-player{position:absolute;left:47%;top:61%;z-index:2;width:8px;height:8px;border-radius:50%;background:#f0cb87;box-shadow:0 0 0 5px rgba(242,200,125,.19),0 0 12px #f4c578;transition:left .2s,top .2s}.map-label{position:absolute;color:#d1c5a6;font-size:7px;letter-spacing:1px;text-shadow:0 1px 3px #162018}.label-winston{left:16%;top:31%}.label-bridge{right:7%;bottom:22%;font-size:6px;color:#c2b08b}.map-tree{position:absolute;color:#546a47;font-size:17px}.t1{left:9%;bottom:11%}.t2{right:20%;top:18%}.t3{left:73%;bottom:2%}.map-footer{display:flex;justify-content:space-between;margin:9px 2px 10px;color:#9e9a8f;font-size:7px;letter-spacing:.6px}.map-footer i{display:inline-block;vertical-align:middle;width:5px;height:5px;border-radius:50%;margin-right:4px}.legend-you{background:#e2bf7c}.legend-npc{background:#9abd7a}.legend-quest{background:#da806b}.map-expand{width:100%;background:rgba(215,178,115,.07);border:1px solid rgba(215,178,115,.2);padding:9px;color:#d6bd91;font-size:8px;letter-spacing:1.05px;text-align:left}.map-expand span{float:right;font-size:12px}.world-panel{padding:13px 15px}.world-panel .section-title{gap:0}.world-panel .live-dot{margin-left:auto;width:5px;height:5px}.pulse-story{display:flex;gap:10px;margin-top:12px}.pulse-icon{flex:0 0 29px;height:29px;display:grid;place-items:center;border:1px solid rgba(207,167,105,.27);background:rgba(207,167,105,.08);font-size:18px;color:#cfaa71}.pulse-story small{font-size:7px;letter-spacing:1px;color:#c5a775}.pulse-story p{font-size:9px;line-height:1.45;color:#c4c0b4;margin-top:4px}.world-meters{border-top:1px solid rgba(255,255,255,.07);margin-top:12px;padding-top:10px}.world-meters>div{position:relative;margin:0 0 8px}.world-meters span{font-size:7px;letter-spacing:.7px;color:#a5a196}.world-meters b{float:right;font-size:8px;font-weight:500;color:#d9c99f}.meter{height:3px;margin-top:5px}.meter i{height:100%;display:block;background:#b4935f;transition:width .35s}.rep-line{height:2px;background:linear-gradient(90deg,#765a3a,#c3a265,#73866a);margin-top:6px}.quick-panel{padding:13px 15px}.quick-grid{margin-top:10px;display:grid;grid-template-columns:1fr 1fr;gap:5px}.quick-grid button{height:35px;text-align:left;background:rgba(255,255,255,.025);border:1px solid rgba(255,255,255,.065);font-size:8px;letter-spacing:.5px;color:#c9c4b8;padding:0 7px}.quick-grid button>span{font-size:13px;color:#d2ad71;margin-right:6px}.quick-grid kbd{float:right;color:#817f75;border:1px solid rgba(255,255,255,.15);font-size:7px;padding:1px 3px}.bottom-hud{position:fixed;z-index:3;bottom:0;left:0;right:0;height:92px;display:flex;align-items:flex-end;justify-content:center;padding-bottom:17px;background:linear-gradient(0deg,rgba(8,12,10,.82),rgba(8,12,10,.16));pointer-events:none}.hotbar{height:53px;display:flex;align-items:stretch;gap:5px;pointer-events:auto}.hotbar-slot{position:relative;width:49px;height:49px;border:1px solid rgba(221,196,154,.25);background:linear-gradient(135deg,rgba(45,48,41,.93),rgba(20,24,21,.9));display:grid;place-items:center;color:#d5c6a5;font-size:20px;box-shadow:0 4px 14px #0005}.hotbar-slot.active{border-color:#d4ad6e;box-shadow:inset 0 0 12px rgba(207,167,104,.14),0 0 13px rgba(205,167,108,.14)}.hotbar-slot kbd{position:absolute;left:4px;top:3px;color:#aaa395;font-size:8px;background:none;border:0}.hotbar-slot.potion{margin-left:7px;color:#bd7667}.hotbar-slot small{position:absolute;bottom:2px;right:4px;font-size:8px;color:#e7d9be}.hotbar-sep{width:1px;background:rgba(210,186,144,.2);height:34px;margin:auto 5px}.weapon-label{align-self:center;margin-left:12px;min-width:120px}.weapon-label small,.weapon-label strong{display:block}.weapon-label small{font-size:7px;letter-spacing:1px;color:#99958a}.weapon-label strong{font-size:8px;letter-spacing:.6px;color:#e2d4b8;margin-top:4px}.weapon-label strong span{color:#c8a772}.interaction-hint{position:absolute;bottom:85px;left:50%;transform:translateX(-50%);background:rgba(18,23,21,.9);border:1px solid rgba(218,190,142,.35);padding:8px 12px;display:flex;align-items:center;gap:9px;font-size:10px;color:#d2cabc;opacity:0;transition:opacity .2s}.interaction-hint.visible{opacity:1}.interaction-hint kbd{background:#c5a06a;color:#191812;padding:3px 6px;font-weight:bold}.interaction-hint b{color:#f0d29a;font-weight:500}.controls-hint{position:absolute;right:34px;bottom:27px;color:#9c9b91;font-size:8px;letter-spacing:.8px}.controls-hint span{color:#d7c7a6;border:1px solid rgba(225,206,171,.25);padding:3px 5px;font-size:7px}.controls-hint i{font-style:normal;color:#686b62;padding:0 4px}.toast{position:fixed;z-index:8;top:88px;left:50%;transform:translate(-50%,-12px);background:rgba(19,25,22,.95);border:1px solid rgba(211,173,110,.42);color:#e2d5b8;font-size:11px;padding:11px 18px;opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.dialogue-overlay,.modal-overlay{position:fixed;inset:0;z-index:7;background:rgba(4,8,7,.55);display:none;align-items:center;justify-content:center;padding:20px}.dialogue-overlay.open,.modal-overlay.open{display:flex}.dialogue-card{width:min(490px,94vw);padding:26px 30px 24px}.close-button{position:absolute;right:13px;top:8px;background:none;border:0;color:#a6a194;font-size:25px}.dialogue-npc{display:flex;align-items:center;gap:16px}.npc-portrait{height:60px;width:60px;display:grid;place-items:center;border:1px solid rgba(212,173,110,.5);background:radial-gradient(circle at 40% 30%,#82704c,#34372e 74%);font:32px Marcellus;color:#e9cf9f}.dialogue-npc small{font-size:8px;letter-spacing:1.1px;color:#c4a16d}.dialogue-npc h2{font:26px Marcellus;margin:4px 0 7px}.affinity{font-size:8px;letter-spacing:.8px;color:#aaa496;display:flex;gap:5px;align-items:center}.affinity span,.affinity b{color:#d6b574}.affinity-track{width:72px;height:3px;background:#35372f;margin-left:3px}.affinity-track i{display:block;height:100%;width:12%;background:#d2ae72}.dialogue-rule{height:1px;background:var(--line);margin:18px 0}.dialogue-text{font:15px/1.7 Marcellus,serif;color:#e1dccf;min-height:74px}.dialogue-choices{display:grid;gap:7px;margin-top:14px}.choice-button{border:1px solid rgba(220,196,151,.17);background:rgba(255,255,255,.025);text-align:left;padding:11px 13px;color:#c9c3b4;font-size:10px;transition:.2s}.choice-button:hover{border-color:#cba870;color:#f0d29a;background:rgba(211,173,110,.09)}.choice-button span{color:#d1ad71;padding-right:8px}.modal{width:min(690px,95vw);max-height:82vh;overflow:auto;padding:27px 30px}.modal-title{font:27px Marcellus;color:#e9dfcb;margin:2px 0 5px}.modal-kicker{font-size:8px;letter-spacing:1.5px;color:#c2a16d}.modal-description{font-size:11px;line-height:1.6;color:#aaa69b;margin:8px 0 18px}.inventory-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.item-card{min-height:83px;border:1px solid rgba(222,198,154,.15);background:rgba(255,255,255,.025);padding:10px;position:relative}.item-icon{font-size:22px;color:#d2b37d}.item-card strong{display:block;font:12px Marcellus;margin-top:5px}.item-card small{display:block;font-size:8px;color:#99958b;margin-top:3px}.item-count{position:absolute;top:8px;right:8px;color:#d2be99;font-size:9px}.craft-layout{display:grid;grid-template-columns:1fr 1.15fr;gap:14px}.recipe-list{display:grid;gap:6px}.recipe{border:1px solid rgba(220,196,151,.14);background:rgba(255,255,255,.025);padding:10px;text-align:left}.recipe.selected{border-color:#bd9863;background:rgba(200,158,96,.1)}.recipe strong{display:block;font:13px Marcellus}.recipe small{font-size:8px;color:#9d9a8e}.recipe-detail{border:1px solid rgba(220,196,151,.15);padding:14px;background:rgba(255,255,255,.02)}.recipe-detail h3{font:18px Marcellus}.recipe-detail p{font-size:10px;color:#aaa69a;line-height:1.5;margin:8px 0}.material-row{display:flex;justify-content:space-between;padding:8px 0;border-top:1px solid rgba(255,255,255,.06);font-size:9px;color:#c4bdad}.material-row b{color:#d0b77e;font-weight:500}.gold-button{border:1px solid rgba(224,188,126,.45);background:linear-gradient(90deg,rgba(172,127,68,.22),rgba(212,173,110,.12));padding:10px 15px;color:#e4c78f;font-size:9px;letter-spacing:1px;margin-top:10px}.gold-button:disabled{opacity:.42;cursor:not-allowed}.journal-entry{border-left:2px solid #c8a66c;background:rgba(255,255,255,.025);padding:12px;margin:10px 0}.journal-entry strong{font:15px Marcellus}.journal-entry p{font-size:10px;line-height:1.6;color:#aaa79a;margin-top:5px}.world-map{height:280px;position:relative;overflow:hidden;border:1px solid rgba(218,190,142,.2);background:radial-gradient(ellipse at 29% 42%,#55634a,#394b3c 35%,transparent 60%),radial-gradient(ellipse at 73% 54%,#5a6145,#384637 36%,transparent 61%),linear-gradient(90deg,#303e35,#526047 48%,#25444a 51%,#354338);}.world-map:before{content:'';position:absolute;inset:0;background-image:radial-gradient(rgba(220,205,166,.14) 1px,transparent 1px);background-size:20px 20px;opacity: