function dialogueChoice(a,action){if(action==='leave'){document.querySelector('#dialogueOverlay').classList.remove('open');return}if(action==='help'){state.ironOre+=2;a.affinity+=8;state.reputation+=5;state.prosperity=Math.min(100,state.prosperity+4);setQuest(1);addXP(120);toast('Quest updated · Iron ore +2 · Edda affinity +8');showDialogue(a);return}if(action==='roads'){state.prosperity=Math.min(100,state.prosperity+12);state.reputation+=9;a.affinity+=6;document.querySelector('#pulseTag').textContent='WINSTON · PLAYER DECISION';document.querySelector('#pulseText').textContent='Your support funded repairs to the old road. Traders have begun returning to Winston.';toast('World changed · Road repairs funded · Prosperity +12');document.querySelector('#dialogueOverlay').classList.remove('open');updateBars();return}if(action==='talk'||action==='lore'){a.affinity+=2;document.querySelector('#dialogueText').textContent=action==='lore'?'A smith listens to the metal. The right heat, the right strike—tools are no substitute for understanding.':'People are nervous about the wolves. The caravan brought seed and salt, but little iron. Someone has to decide what Winston needs most.';document.querySelector('#affinityValue').textContent=a.affinity;document.querySelector('#affinityFill').style.width=Math.min(100,a.affinity)+'%';toast(`${a.name} affinity increased`);return}if(action==='craft'){document.querySelector('#dialogueOverlay').classList.remove('open');openModal('craft');return}if(action==='wolves'){state.reputation+=4;toast('Winston Guard reputation +4 · Wolves marked on your map');document.querySelector('#dialogueOverlay').classList.remove('open');return}if(action==='goods'){toast('Mira has nothing you need right now');return}}
document.querySelector('#closeDialogue').onclick=()=>document.querySelector('#dialogueOverlay').classList.remove('open');
function openModal(type){const overlay=document.querySelector('#modalOverlay'),content=document.querySelector('#modalContent');overlay.classList.add('open');if(type==='inventory'){content.innerHTML=`<div class="modal-kicker">YOUR BELONGINGS</div><h1 class="modal-title">Inventory</h1><p class="modal-description">A traveler's kit. Materials gathered and gifts received along the road.</p><div class="inventory-grid">${[['⚒','Iron ore',state.ironOre,'Raw material'],['▰','Iron ingot',state.ingot,'Crafting material'],['♣','Hardwood',state.wood,'Raw material'],['✿','Moonleaf',state.herb,'Herb'],['◈','Gold coin',state.coins,'Currency'],['⚔','Ironbound sabre',state.quest>=3?1:0,'Weapon · Rare']].map(x=>`<div class="item-card"><span class="item-count">×${x[2]}</span><div class="item-icon">${x[0]}</div><strong>${x[1]}</strong><small>${x[3]}</small></div>`).join('')}</div>`}else if(type==='craft'){content.innerHTML=`<div class="modal-kicker">WINSTON · KHAN’S FORGE</div><h1 class="modal-title">The Smithy</h1><p class="modal-description">Study the design, gather materials, and shape the world one piece at a time. Manual craft grants a small bonus to quality.</p><div class="craft-layout"><div class="recipe-list">${['Ironbound Sabre','Traveler’s Buckler','Field Repair Kit'].map((n,i)=>`<button class="recipe ${state.selectedRecipe===i?'selected':''}" data-recipe="${i}"><strong>${n}</strong><small>${['Weapon · Rare potential','Shield · Common','Utility · Common'][i]}</small></button>`).join('')}</div><div class="recipe-detail" id="recipeDetail"></div></div>`;content.querySelectorAll('.recipe').forEach(b=>b.onclick=()=>{state.selectedRecipe=+b.dataset.recipe;openModal('craft')});renderRecipe()}else if(type==='journal'){content.innerHTML=`<div class="modal-kicker">YOUR JOURNEY</div><h1 class="modal-title">Journal</h1><p class="modal-description">The continent is not a story written in advance. It remembers what its people choose.</p><div class="journal-entry"><strong>${['A Smith’s Request','Iron for the Forge','A New Edge','A Living Town'][state.quest]}</strong><p>${['Find Traveler Edda by the old bridge.','Take the ore Edda gave you to Khan’s forge.','Use the smithy to craft an Ironbound Sabre.','Winston’s future is being shaped by your actions.'][state.quest]}</p></div><div class="journal-entry"><strong>World Chronicle · Day 1</strong><p>${document.querySelector('#pulseText').textContent}</p></div>`}else if(type==='world'){content.innerHTML=`<div class="modal-kicker">WEST CONTINENT · YOUR WORLD</div><h1 class="modal-title">The world is wide.</h1><p class="modal-description">This is a living region on a continent without borders. Discover routes, help communities, and decide what thrives. Select a destination to travel.</p><div class="world-map"><span class="continent-label west-label">WEST CONTINENT</span><span class="continent-label east-label">EAST CONTINENT</span><span class="sea-label">RED SEA</span><span class="map-location" style="left:25%;top:38%" data-name="Winston · Here"></span><span class="map-location" style="left:18%;top:70%" data-name="Bairan · 18 gold"></span><span class="map-location" style="left:34%;top:65%" data-name="Reidan · Beyond the sands"></span><span class="map-location" style="left:73%;top:45%" data-name="Pangea · Uncharted"></span></div><div class="world-map-legend"><span>West Continent · 560m region loaded</span><span>⏱ 3:1 world time</span></div><button class="event-choice" id="worldEvent"><b>Community decision · Winston</b>Choose what the people should prioritize next. Your choice changes local prosperity and reputation.</button>`;content.querySelector('#worldEvent').onclick=()=>openModal('decision')}else if(type==='decision'){content.innerHTML=`<div class="modal-kicker">PLAYER-DRIVEN WORLD · WINSTON</div><h1 class="modal-title">What should Winston become?</h1><p class="modal-description">The town council has asked you to guide the next community effort. Every decision has lasting consequences.</p><button class="event-choice" data-choice="forge"><b>Restore Khan’s forge</b>Invest 4 gold. Smithing output rises; Khan’s affinity and local industry improve.</button><button class="event-choice" data-choice="road"><b>Repair the trade road</b>Invest 3 gold. Increase prosperity and make future caravans safer.</button><button class="event-choice" data-choice="fields"><b>Support the outer farms</b>Invest 2 gold. Improve food supply and attract new residents.</button>`;content.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>worldDecision(b.dataset.choice))}}
function renderRecipe(){const el=document.querySelector('#recipeDetail');if(!el)return;let i=state.selectedRecipe,data=[['Ironbound Sabre','A balanced blade with a dark iron core. A dependable weapon made for a long road.',['Iron ore ×2','Hardwood ×1'],2,1],['Traveler’s Buckler','A light shield for blocking and countering.',['Iron ore ×1','Hardwood ×2'],1,2],['Field Repair Kit','Basic materials to restore worn equipment.',['Iron ore ×1','Moonleaf ×1'],1,0]][i];el.innerHTML=`<h3>${data[0]}</h3><p>${data[1]}</p>${data[2].map(m=>`<div class="material-row"><span>${m}</span><b>REQUIRED</b></div>`).join('')}<div class="material-row"><span>Current skill · Apprentice</span><b>68% quality</b></div><button class="gold-button" id="craftButton">⚒ &nbsp; BEGIN CRAFT</button>`;const b=el.querySelector('#craftButton');b.onclick=()=>craftItem(i)}
function craftItem(i){const needs=[[2,1,0],[1,2,0],[1,0,1]][i];if(state.ironOre<needs[0]||state.wood<needs[1]||state.herb<needs[2]){toast('Missing materials · Gather more in the wild');return}state.ironOre-=needs[0];state.wood-=needs[1];state.herb-=needs[2];if(i===0){state.quest=3;state.prosperity=Math.min(100,state.prosperity+9);state.reputation+=12;document.querySelector('#pulseTag').textContent='WINSTON · CRAFTED BY YOU';document.querySelector('#pulseText').textContent='A new sabre leaves Khan’s forge. The apprentice says your name will be remembered.';setQuest(3);addXP(280);toast('Craft complete · Ironbound Sabre · Winston prosperity +9')}else{state.ingot++;toast(i===1?'Traveler’s Buckler crafted':'Field Repair Kit crafted')}updateBars();openModal('inventory')}
function worldDecision(choice){let cost=choice==='forge'?4:choice==='road'?3:2;if(state.coins<cost){toast(`You need ${cost} gold to fund this effort`);return}state.coins-=cost;if(choice==='forge'){state.prosperity=Math.min(100,state.prosperity+15);actors.find(a=>a.id==='khan').affinity+=12;document.querySelector('#pulseTag').textContent='WINSTON · INDUSTRY RESTORED';document.querySelector('#pulseText').textContent='You invested in Khan’s forge. New tools and eager apprentices have brought the smithy back to life.';state.reputation+=12}else if(choice==='road'){state.prosperity=Math.min(100,state.prosperity+12);document.querySelector('#pulseTag').textContent='WINSTON · TRADE ROAD REPAIRED';document.querySelector('#pulseText').textContent='Your gold paid for the old road. Caravans return, and travelers speak well of Winston.';state.reputation+=10}else{state.prosperity=Math.min(100,state.prosperity+8);document.querySelector('#pulseTag').textContent='WINSTON · FARMS SUPPORTED';document.querySelector('#pulseText').textContent='New seed and tools reach the outer farms. A steadier harvest means fewer hungry homes.';state.reputation+=8}updateBars();document.querySelector('#modalOverlay').classList.remove('open');toast('World changed by your decision · Community remembers');}
document.querySelector('#closeModal').onclick=()=>document.querySelector('#modalOverlay').classList.remove('open');document.querySelector('#modalOverlay').addEventListener('click',e=>{if(e.target.id==='modalOverlay')e.currentTarget.classList.remove('open')});

