document.querySelector('#modalOverlay').addEventListener('click',e=>{if(e.target.id==='modalOverlay')e.currentTarget.classList.remove('open')});
function doInteract(){if(nearest){showDialogue(nearest);return}let forgeDist=Math.hypot(player.position.x+43,player.position.z-12);if(forgeDist<12){openModal('craft');return}toast('No one is close enough to interact with')}
function attack(){if(state.attackCd>0)return;state.attackCd=.62;state.stamina=Math.max(0,state.stamina-7);let target=null,d=7;for(const w of wolves){if(!w.userData.alive)continue;const q=player.position.distanceTo(w.position);if(q<d){d=q;target=w}}if(target){target.userData.hp-=24;target.position.add(new THREE.Vector3(Math.sin(yaw),0,Math.cos(yaw)).multiplyScalar(1.7));toast(target.userData.hp<=0?'Wolf defeated · XP +35':'Hit · Wolf staggered');document.querySelector('#combatFlash').classList.add('on');setTimeout(()=>document.querySelector('#combatFlash').classList.remove('on'),110);if(target.userData.hp<=0){target.userData.alive=false;target.visible=false;addXP(35);state.herb+=1;document.querySelector('#pulseText').textContent='The road is safer after a wolf pack was driven off near Winston.';state.prosperity=Math.min(100,state.prosperity+1)}}else toast('Your blade cuts through the air');updateBars()}
