function person(x,z,coat,accent=0xd4b16f,isPlayer=false){const g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);scene.add(g);g.userData={};const body=mesh(new THREE.CapsuleGeometry(.48,.85,4,8),mat(coat),0,1.15,0,g);body.scale.set(.84,1, .58);mesh(new THREE.SphereGeometry(.38,12,10),M.skin,0,2.08,0,g);mesh(new THREE.CylinderGeometry(.39,.5,.18,8),mat(accent),0,2.34,0,g);for(let side of [-1,1]){mesh(new THREE.CylinderGeometry(.12,.14,.72,7),mat(coat),side*.37,.56,0,g);mesh(new THREE.CylinderGeometry(.1,.12,.76,7),mat(coat),side*.57,1.34,0,g).rotation.z=side*-.12}if(isPlayer){const cape=mesh(new THREE.ConeGeometry(.48,1.2,5),mat(0x273c3b),0,1.08,-.28,g);cape.rotation.x=-.1;const sword=mesh(new THREE.BoxGeometry(.09,.95,.12),M.iron,.72,1.2,.05,g);sword.rotation.z=-.42}g.userData.body=body;return g}
const player=person(0,19,0x314743,0xc3a36a,true);const actors=[{id:'edda',name:'Traveler Edda',role:'TRAVELER · WANDERER',char:'E',x:3,z:-2,color:0x765543,affinity:12,type:'npc'},{id:'khan',name:'Khan',role:'MASTER BLACKSMITH',char:'K',x:-44,z:19,color:0x574b3e,affinity:18,type:'smith'},{id:'guard',name:'Winston Guard',role:'TOWN GUARD',char:'G',x:32,z:18,color:0x536b62,affinity:4,type:'guard'},{id:'merchant',name:'Mira the Peddler',role:'TRAVELING MERCHANT',char:'M',x:18,z:48,color:0x72594c,affinity:7,type:'merchant'}];
