function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function updateBars(){document.querySelector('#hpFill').style.width=state.hp+'%';document.querySelector('#hpText').textContent=`${state.hp} / 100`;document.querySelector('#staminaFill').style.width=state.stamina+'%';document.querySelector('#staminaText').textContent=`${Math.round(state.stamina)} / 100`;document.querySelector('#xpFill').style.width=(state.xp/3200*100)+'%';document.querySelector('#prosperityValue').textContent=state.prosperity+'%';document.querySelector('#prosperityMeter').style.width=state.prosperity+'%';document.querySelector('#reputationValue').textContent=state.reputation>20?'RESPECTED':state.reputation<0?'SUSPECTED':'NEUTRAL'}
function setQuest(n){state.quest=n;const titles=['A Smith’s Request','Iron for the Forge','A New Edge','A Living Town'];const desc=['Find the traveler near the old stone bridge.','Bring the iron ore Edda gave you to Khan’s forge.','Craft an ironbound sabre at the village forge.','Your choices shape Winston. Help the people prosper.'];const steps=['Speak with Traveler Edda','Take the ore to Khan','Craft an Ironbound Sabre','The next chapter is yours'];document.querySelector('#questTitle').textContent=titles[n];document.querySelector('#questDesc').textContent=desc[n];document.querySelector('#questStep').textContent=steps[n]}
