function showDialogue(a){if(!a)return;document.querySelector('#dialogueOverlay').classList.add('open');document.querySelector('#npcName').textContent=a.name;document.querySelector('#npcRole').textContent=a.role;document.querySelector('#npcPortrait').textContent=a.char;document.querySelector('#affinityValue').textContent=a.affinity;document.querySelector('#affinityFill').style.width=Math.min(100,a.affinity)+'%';const text=document.querySelector('#dialogueText'),choices=document.querySelector('#dialogueChoices');choices.innerHTML='';let opts=[];if(a.id==='edda'){text.textContent=state.quest===0?'The bridge is a mess, the roads are worse, and the smithy has run out of iron. Could you help? I have a few pieces of ore to spare.':state.quest===1?'Khan is at the forge, just west of the village. He can put that ore to good use.':'Winston is changing. I can feel it in the way people speak to one another.';opts=state.quest===0?[['I’ll take the ore to Khan.','help'],['The town should repair its roads first.','roads'],['I’m in a hurry.','leave']]:[['How are things in Winston?','talk'],['Goodbye.','leave']]}else if(a.type==='smith'){text.textContent=state.quest<2?'You’ve brought ore? Good. A steady hand and honest steel—that’s what keeps a town alive.':'A fine edge starts with patience. Want to work the forge?';opts=[['Let’s craft something useful.','craft'],['Tell me about your craft.','lore'],['Goodbye.','leave']]}else if(a.type==='guard'){text.textContent='Keep your blade sheathed inside the walls, traveler. The woods have grown restless, though.';opts=[['I’ll help keep the roads safe.','wolves'],['Understood.','leave']]}else{text.textContent='Fine wares, fair prices. But a town’s real wealth is its people.';opts=[['What does Winston need?','roads'],['Show me your goods.','goods'],['Goodbye.','leave']]}
