function renderRecipe(){const el=document.querySelector('#recipeDetail');if(!el)return;let i=state.selectedRecipe,data=[['Ironbound Sabre','A balanced blade with a dark iron core. A dependable weapon made for a long road.',['Iron ore ×2','Hardwood ×1'],2,1],['Traveler’s Buckler','A light shield for blocking and countering.',['Iron ore ×1','Hardwood ×2'],1,2],['Field Repair Kit','Basic materials to restore worn equipment.',['Iron ore ×1','Moonleaf ×1'],1,0]][i];el.innerHTML=`<h3>${data[0]}</h3><p>${data[1]}</p>${data[2].map(m=>`<div class="material-row"><span>${m}</span><b>REQUIRED</b></div>`).join('')}<div class="material-row"><span>Current skill · Apprentice</span><b>68% quality</b></div><button class="gold-button" id="craftButton">⚒ &nbsp; BEGIN CRAFT</button>`;const b=el.querySelector('#craftButton');b.onclick=()=>craftItem(i)}
