const joyEl=document.querySelector('#joystick'),knob=document.querySelector('#joyKnob');let joyPointer=null;joyEl.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joyEl.setPointerCapture(e.pointerId);moveJoy(e)});joyEl.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)moveJoy(e)});function moveJoy(e){let r=joyEl.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),lim=r.width*.33,l=Math.hypot(dx,dy);if(l>lim){dx=dx/l*lim;dy=dy/l*lim}joy.x=dx/lim;joy.y=dy/lim;knob.style.transform=`translate(${dx}px,${dy}px)`}function endJoy(e){if(e.pointerId===joyPointer){joyPointer=null;joy.x=joy.y=0;knob.style.transform=''}}joyEl.addEventListener('pointerup',endJoy);joyEl.addEventListener('pointercancel',endJoy);
