import { createRequire } from 'node:module';
const require=createRequire(`${process.env.HOME}/.local/share/omgithub-playwright/package.json`);
const {chromium}=require('playwright');
const cfg=require(`${process.env.HOME}/.local/share/omgithub-playwright/linux.json`);
const browser=await chromium.launch(cfg.browser.launchOptions);
const errors=[], bad=[];
const page=await browser.newPage({viewport:{width:1440,height:900}});
page.on('pageerror',e=>errors.push(e.message));
page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
page.on('response',r=>{if(r.status()>=400&&new URL(r.url()).origin==='http://127.0.0.1:5173')bad.push(`${r.status()} ${r.url()}`)});
await page.goto('http://127.0.0.1:5173',{waitUntil:'load'});
await page.waitForSelector('canvas');
await page.waitForTimeout(1000);
console.log('favicon', await page.locator('link[rel="icon"]').getAttribute('href'));
console.log('initial nearby', (await page.locator('#nearbyList').innerText()).replaceAll('\n',' | '));
await page.keyboard.down('w');
await page.waitForTimeout(16000);
await page.keyboard.up('w');
console.log('after movement nearby', (await page.locator('#nearbyList').innerText()).replaceAll('\n',' | '));
await page.keyboard.press('e');
const isOpen=await page.locator('#dialogueOverlay').evaluate(e=>e.classList.contains('open'));
console.log('dialogue open',isOpen);
if(isOpen){
  console.log('dialogue choices', await page.locator('#dialogueChoices').innerText());
  await page.locator('#dialogueChoices button').first().click();
  console.log('quest after choice',await page.locator('#questTitle').innerText());
}
await page.keyboard.press('k');
console.log('craft modal open',await page.locator('#modalOverlay').evaluate(e=>e.classList.contains('open')));
await page.locator('#craftButton').click();
console.log('inventory after craft',await page.locator('#modalContent').innerText().then(s=>s.replace(/\s+/g,' ').slice(-300)));
console.log('desktop errors',errors,'local bad responses',bad);
const mobile=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true,deviceScaleFactor:1});
const mobileErrors=[];mobile.on('pageerror',e=>mobileErrors.push(e.message));
await mobile.goto('http://127.0.0.1:5173',{waitUntil:'load'});await mobile.waitForSelector('canvas');
console.log('mobile controls visible',await mobile.locator('#mobileControls').evaluate(e=>getComputedStyle(e).display!=='none'));
const joy=await mobile.locator('#joystick').boundingBox();
await mobile.mouse.move(joy.x+joy.width/2,joy.y+joy.height/2);await mobile.mouse.down();await mobile.mouse.move(joy.x+joy.width/2+25,joy.y+joy.height/2-20,{steps:4});await mobile.waitForTimeout(1200);await mobile.mouse.up();
await mobile.locator('#mobileInteract').click();
console.log('mobile joystick knob reset',await mobile.locator('#joyKnob').getAttribute('style'));
console.log('mobile interact feedback',await mobile.locator('#toast').innerText());
await mobile.screenshot({path:'/tmp/opencode/recheck/latest/mobile-final.png'});
console.log('mobile errors',mobileErrors);
await page.screenshot({path:'/tmp/opencode/recheck/latest/desktop-final.png'});
await browser.close();

