import { createRequire } from 'node:module';
const require=createRequire(`${process.env.HOME}/.local/share/omgithub-playwright/package.json`);
const {chromium}=require('playwright');
const cfg=require(`${process.env.HOME}/.local/share/omgithub-playwright/linux.json`);
const browser=await chromium.launch(cfg.browser.launchOptions);
const desktop=await browser.newPage({viewport:{width:1440,height:900}});
const errors=[];desktop.on('pageerror',e=>errors.push(e.message));
await desktop.goto('http://127.0.0.1:5173',{waitUntil:'load'});await desktop.waitForSelector('canvas');await desktop.waitForTimeout(500);
const dist=async page=>Number((await page.locator('#nearbyList').innerText()).match(/Traveler Edda\s+(\d+)M/)?.[1]||999);
console.log('desktop initial Edda',await dist(desktop));
await desktop.keyboard.down('w');
for(let i=0;i<16;i++){await desktop.waitForTimeout(250);if(await dist(desktop)<9)break}
await desktop.keyboard.up('w');await desktop.waitForTimeout(200);
console.log('desktop Edda after W',await dist(desktop));
await desktop.keyboard.press('e');
console.log('desktop dialogue',await desktop.locator('#dialogueOverlay').evaluate(e=>e.classList.contains('open')));
console.log('choices',await desktop.locator('#dialogueChoices').innerText());
await desktop.locator('#dialogueChoices button').first().click();
console.log('quest after choice',await desktop.locator('#questTitle').innerText(),'dialogue still open',await desktop.locator('#dialogueOverlay').evaluate(e=>e.classList.contains('open')));
const mobile=await browser.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true,deviceScaleFactor:1});mobile.on('pageerror',e=>errors.push('mobile: '+e.message));
await mobile.goto('http://127.0.0.1:5173',{waitUntil:'load'});await mobile.waitForSelector('canvas');await mobile.waitForTimeout(500);
const before=await mobile.locator('#mapPlayer').getAttribute('style');const joy=await mobile.locator('#joystick').boundingBox();
await mobile.mouse.move(joy.x+joy.width/2,joy.y+joy.height/2);await mobile.mouse.down();await mobile.mouse.move(joy.x+joy.width/2+8,joy.y+joy.height/2-40,{steps:5});await mobile.waitForTimeout(1600);await mobile.mouse.up();await mobile.waitForTimeout(400);
const after=await mobile.locator('#mapPlayer').getAttribute('style');console.log('mobile map position before/after joystick',before,after,'nearby',await mobile.locator('#nearbyList').innerText());
await mobile.locator('#mobileInteract').click();console.log('mobile interact',await mobile.locator('#dialogueOverlay').evaluate(e=>e.classList.contains('open')),await mobile.locator('#toast').innerText());
console.log('browser errors',errors);
await desktop.screenshot({path:'/tmp/opencode/recheck/latest/desktop-final.png'});await mobile.screenshot({path:'/tmp/opencode/recheck/latest/mobile-final.png'});await browser.close();

