cat > /tmp/opencode/perf-capture.mjs <<'EOF'
import { createRequire } from 'node:module';
const require=createRequire(`${process.env.HOME}/.local/share/omgithub-playwright/package.json`);
const {chromium}=require('playwright');
const cfg=require(`${process.env.HOME}/.local/share/omgithub-playwright/linux.json`);
const browser=await chromium.launch(cfg.browser.launchOptions);const page=await browser.newPage({viewport:{width:1440,height:900}});await page.goto('http://127.0.0.1:5173',{waitUntil:'load'});await page.waitForSelector('canvas');await page.waitForTimeout(1000);
const result=await page.evaluate(async()=>{let n=0,start=performance.now();return await new Promise(resolve=>{function tick(){n++;if(performance.now()-start>=3000)resolve({frames:n,seconds:(performance.now()-start)/1000,fps:n/((performance.now()-start)/1000)});else requestAnimationFrame(tick)}requestAnimationFrame(tick)})});
await page.screenshot({path:'/tmp/opencode/recheck/latest/desktop-final.png'});console.log('desktop RAF sample',result);await browser.close();
EOF
xvfb-run -a node /tmp/opencode/perf-capture.mjs
